import sys
import six
import logging
from socket import socket, error, AF_INET, SOCK_STREAM
from subprocess import call
from functools import partial
from taf.transport.ssh.ssh_keywords import SSHManager

from ..timeout import Timeout
from .exception import ProtocolError, PingError, SshError, HwApiError

logger = logging.getLogger('agent_ute')


class _Runner(object):

    def __init__(self, action_method):
        self._action_method = action_method

    def run(self, tries=1, error=ProtocolError('All commands failed')):
        """Run action method until result equals 0. Specified error will be raised if all tries return result different than 0."""
        for _ in range(tries):
            result = self._action_method()
            if result == 0:
                return
        raise error

    def wait_until_passed(self, amount=1, timeout=15, error=ProtocolError('Timeout occurs')):
        """Run action method until amount of results passed. Specified error will be raised if timeout occurs."""
        _passed_condition = lambda x: x == 0
        self._wait_until_condition(_passed_condition, amount, timeout, error)

    def wait_until_failed(self, amount=1, timeout=15, error=ProtocolError('Timeout occurs')):
        """Run action method until amount of results failed. Specified error will be raised if timeout occurs."""
        _failed_condition = lambda x: x != 0
        self._wait_until_condition(_failed_condition, amount, timeout, error)

    def _wait_until_condition(self, condition, amount, timeout, error):
        timeout = Timeout(timeout)
        tried = 0
        while timeout.is_not_reached():
            result = self._action_method()
            tried = tried + 1 if condition(result) else 0
            if tried == amount:
                return
        raise error


class Ping(object):
    """Class to execute ping command for specific host

    ::

        ping = Ping(ip='1.1.1.1')
        ping.run(tries=10)
        ping.wait_until_failed(amount=15, timeout=120)
        ping.wait_until_passed(amount=15, timeout=480)

    """

    CMD_TEMPLATE = 'ping {ip} -c 2 > /dev/null'

    def __init__(self, ip):
        self._ip = ip
        self._runner = _Runner(partial(self._run_action, ip))

    def run(self, tries=1):
        """Run ping command/s.

        :param integer tries: Number of tries to execute.
        :raise: PingError if all ping commands failed.
        """
        error = PingError('All ping commands ({tries}) failed for host {ip}'.format(tries=tries, ip=self._ip))
        self._runner.run(tries=tries, error=error)

    def wait_until_passed(self, amount=1, timeout=15):
        """Run ping command/s and wait until amount of commands passed or timeout occurs.

        :param integer amount: Amount of passed commands to passed whole condition.
        :param integer timeout: Timeout
        :raise: PingError if timeout occurs
        """
        error = PingError('Timeout ({timeout} second/s) occurs for host {ip}'.format(timeout=timeout, ip=self._ip))
        self._runner.wait_until_passed(amount=amount, timeout=timeout, error=error)

    def wait_until_failed(self, amount=1, timeout=15):
        """Run ping command/s and wait until amount of command failed or timeout occurs.

        :param integer amount: Amount of failed commands to passed whole condition.
        :param integer timeout: Timeout
        :raise: PingError if timeout occurs
        """
        error = PingError('Host {ip} didn\'t disappear before timeout ({timeout} second/s)'.format(ip=self._ip, timeout=timeout))
        self._runner.wait_until_failed(amount=amount, timeout=timeout, error=error)

    def _run_action(self, ip):
        cmd = Ping.CMD_TEMPLATE.format(ip=ip)
        return call(cmd, shell=True)


class Ssh(object):
    """Class to execute ssh command for specific host

    ::

        ssh = Ssh(ip='1.1.1.1', username='test', password='test')
        ssh.run(tries=10)
        ssh.wait_until_failed(amount=15, timeout=120)
        ssh.wait_until_passed(amount=15, timeout=480)

    """
    def __init__(self, ip, username, password):
        self._ip = ip
        self._runner = _Runner(partial(self._run_action, ip, username, password))

    def run(self, tries=1):
        """Run SSH command/s.

        :param integer tries: Number of tries to execute.
        :raise: SshError if all SSH commands failed.
        """
        error = SshError('All ({tries}) SSH connections failed for host {ip}'.format(tries=tries, ip=self._ip))
        self._runner.run(tries=tries, error=error)

    def wait_until_passed(self, amount=1, timeout=15):
        """Run ssh command/s and wait until amount of command passed or timeout occurs.

        :param integer amount: Amount of passed commands to passed whole condition.
        :param integer timeout: Timeout
        :raise: SshError if timeout occurs
        """
        error = SshError('Timeout ({timeout} second/s) occurs for host {ip}'.format(timeout=timeout, ip=self._ip))
        self._runner.wait_until_passed(amount=amount, timeout=timeout, error=error)

    def wait_until_failed(self, amount=1, timeout=15):
        """Run ssh command/s and wait until amount of command failed or timeout occurs.

        :param integer amount: Amount of failed commands to passed whole condition.
        :param integer timeout: Timeout
        :raise: SshError if timeout occurs
        """
        error = SshError('All SSH connections to host {ip} passed before timeout ({timeout} second/s)'.format(ip=self._ip, timeout=timeout))
        self._runner.wait_until_failed(amount=amount, timeout=timeout, error=error)

    def _run_action(self, ip, username, password):
        try:
            manager = SSHManager()
            manager.connect_to(ip, username, password, port=22)
            return 0
        except Exception:
            return 1


class HwApi(object):
    """A class for checking if HWAPI works on given FSM.

    In agents, HWAPI is mostly needed by puttibatti during the SW update. The check may fail if RnD ports and/or SSH service is disabled."""

    PORT = 15003

    def __init__(self, ip, port=PORT):
        self.logger = logger
        self.ip = ip
        self.port = port

    def wait_until_passed(self, timeout):
        """Waits until HWAPI is reachable or timeout is reached, in which case an HwApiError is raised"""
        sock = socket(AF_INET, SOCK_STREAM)
        sock.settimeout(timeout)
        try:
            sock.connect((self.ip, self.port))
        except error:
            logger.debug('Could not connect to HWAPI', exc_info=sys.exc_info())
            raise HwApiError("Could not connect to HWAPI")
        else:
            sock.close()

    def _log_debug(self, message):
        if self.logger is not None:
            self.logger.debug(message)
